window.CODE_INDEX = {"classes":{"AuthorFeedAPI":{"appearsIn":[["home","h-classes","Logic \u00b7 class diagram"]],"code":"export class AuthorFeedAPI implements FeedAPI {\n  client: Client\n  _params: GetAuthorFeedParams\n\n  constructor({\n    client,\n    feedParams,\n  }: {\n    client: Client\n    feedParams: GetAuthorFeedParams\n  }) {\n    this.client = client\n    this._params = feedParams\n  }\n\n  get params() {\n    const params = {...this._params}\n    params.includePins = params.filter === 'posts_and_author_threads'\n    return params\n  }\n\n  async peekLatest(): Promise<app.bsky.feed.defs.FeedViewPost> {\n    const data = await this.client.call(app.bsky.feed.getAuthorFeed, {\n      ...this.params,\n      limit: 1,\n    })\n    return data.feed[0]\n  }\n\n  async fetch({\n    cursor,\n    limit,\n  }: {\n    cursor: string | undefined\n    limit: number\n  }): Promise<FeedAPIResponse> {\n    /*\n     * A failed request rejects rather than resolving, so the error propagates\n     * to the query and drives the feed error UI (blocked actor, rate limit).\n     * The agent behaved the same way - its `success` flag was only ever true -\n     * so the empty-page branch this replaces was unreachable.\n     */\n    const data = await this.client.call(app.bsky.feed.getAuthorFeed, {\n      ...this.params,\n      cursor,\n      limit,\n    })\n    return {\n      cursor: data.cursor,\n      feed: this._filter(data.feed),\n    }\n  }\n\n  _filter(feed: app.bsky.feed.defs.FeedViewPost[]) {\n    if (this.params.filter === 'posts_and_author_threads') {\n      return feed.filter(post => {\n        const isReply = post.reply\n        const isRepost = bsky.isType(\n          app.bsky.feed.defs.reasonRepost,\n          post.reason,\n        )\n        const isPin = bsky.isType(app.bsky.feed.defs.reasonPin, post.reason)\n        if (!isReply) return true\n        if (isRepost || isPin) return true\n        return isReply && isAuthorReplyChain(this.params.actor, post, feed)\n      })\n    }\n\n    return feed\n  }\n}","file":"src/lib/api/feed/author.ts","kind":"class","line":11,"members":{"_filter":[64,80],"_params":[13,13],"client":[12,12],"constructor":[15,24],"fetch":[40,62],"params":[26,30],"peekLatest":[32,38]},"supers":["FeedAPI"]},"CustomFeedAPI":{"alsoIn":["src/features/followingV2/home/api/custom.ts"],"appearsIn":[["home","h-classes","Logic \u00b7 class diagram"]],"code":"export class CustomFeedAPI implements FeedAPI {\n  client: Client\n  params: GetCustomFeedParams\n  userInterests?: string\n\n  constructor({\n    client,\n    feedParams,\n    userInterests,\n  }: {\n    client: Client\n    feedParams: GetCustomFeedParams\n    userInterests?: string\n  }) {\n    this.client = client\n    this.params = feedParams\n    this.userInterests = userInterests\n  }\n\n  async peekLatest(): Promise<app.bsky.feed.defs.FeedViewPost> {\n    const contentLangs = getContentLanguages().join(',')\n    const data = await this.client.call(\n      app.bsky.feed.getFeed,\n      {\n        ...this.params,\n        limit: 1,\n      },\n      {\n        headers: {\n          ...createBskyFeedHeaders(this.params.feed),\n          'Accept-Language': contentLangs,\n        },\n      },\n    )\n    return data.feed[0]\n  }\n\n  async fetch({\n    cursor,\n    limit,\n    signal,\n  }: {\n    cursor: string | undefined\n    limit: number\n    signal?: AbortSignal\n  }): Promise<FeedAPIResponse> {\n    const contentLangs = getContentLanguages().join(',')\n    const isBlueskyOwned = isBlueskyOwnedFeed(this.params.feed)\n\n    /*\n     * The authed branch rejects on failure, so the error propagates to the\n     * query and drives the feed error UI (feedgen offline, misconfigured, rate\n     * limited). Only the logged-out branch can resolve without data, and it\n     * signals that with a null body.\n     */\n    const data = this.client.did\n      ? await this.client.call(\n          app.bsky.feed.getFeed,\n          {\n            ...this.params,\n            cursor,\n            limit,\n          },\n          {\n            signal,\n            headers: {\n              ...createBskyFeedHeaders(this.params.feed),\n              ...(isBlueskyOwned\n                ? createBskyTopicsHeader(this.userInterests)\n                : {}),\n              'Accept-Language': contentLangs,\n            },\n          },\n        )\n      : await loggedOutFetch({...this.params, cursor, limit}, signal)\n\n    if (!data) {\n      return {\n        feed: [],\n      }\n    }\n\n    // NOTE\n    // some custom feeds fail to enforce the pagination limit\n    // so we manually truncate here\n    // -prf\n    const feed =\n      data.feed.length > limit ? data.feed.slice(0, limit) : data.feed\n    return {\n      cursor: data.cursor,\n      feed,\n    }\n  }\n}","file":"src/lib/api/feed/custom.ts","kind":"class","line":23,"members":{"client":[24,24],"constructor":[28,40],"fetch":[60,115],"params":[25,25],"peekLatest":[42,58],"userInterests":[26,26]},"supers":["FeedAPI"]},"FeedAPI":{"alsoIn":["src/features/followingV2/home/api/types.ts"],"appearsIn":[["home","h-classes","Logic \u00b7 class diagram"],["index","h-services","Services \u00b7 what the screens share"]],"code":"export interface FeedAPI {\n  peekLatest(): Promise<app.bsky.feed.defs.FeedViewPost>\n  fetch({\n    cursor,\n    limit,\n    signal,\n  }: {\n    cursor: string | undefined\n    limit: number\n    signal?: AbortSignal\n  }): Promise<FeedAPIResponse>\n}","file":"src/lib/api/feed/types.ts","kind":"interface","line":8,"members":{"fetch":[10,18],"peekLatest":[9,9]},"supers":[]},"FeedTrendingTopicsInterstitial":{"appearsIn":[["home","h-widgets","Screen \u00b7 component composition"]],"code":"export function FeedTrendingTopicsInterstitial({\n  feedSliceIndex,\n}: {\n  feedSliceIndex: number\n}) {\n  const {enabled} = useTrendingConfig()\n  const {trendingDisabled} = useTrendingSettings()\n  const {rightNavVisible} = useLayoutBreakpoints()\n\n  return enabled && !trendingDisabled && !rightNavVisible ? (\n    <Inner feedSliceIndex={feedSliceIndex} />\n  ) : null\n}","file":"src/components/interstitials/FeedTrendingTopics.tsx","kind":"component","line":40,"members":{"feedSliceIndex":[40,44]},"supers":[]},"FollowingEmptyState":{"appearsIn":[["home","h-widgets","Screen \u00b7 component composition"]],"code":"export function FollowingEmptyState() {\n  const {t: l} = useLingui()\n  const pal = usePalette('default')\n  const navigation = useNavigation<NavigationProp>()\n\n  const onPressFindAccounts = useCallback(() => {\n    if (IS_WEB) {\n      navigation.navigate('Search', {})\n    } else {\n      navigation.dispatch(getTabNavigationAction('Search'))\n      navigation.popToTop()\n    }\n  }, [navigation])\n\n  const onPressDiscoverFeeds = useCallback(() => {\n    navigation.navigate('Feeds')\n  }, [navigation])\n\n  return (\n    <View style={styles.container}>\n      <View style={styles.inner}>\n        <View style={styles.iconContainer}>\n          <MagnifyingGlassIcon style={[styles.icon, pal.text]} size={62} />\n        </View>\n        <Text type=\"xl-medium\" style={[s.textCenter, pal.text]}>\n          <Trans>\n            Your following feed is empty! Follow more users to see what's\n            happening.\n          </Trans>\n        </Text>\n        <View style={[a.mt_xl, a.align_center]}>\n          <Button\n            label={l`Find accounts to follow`}\n            onPress={onPressFindAccounts}\n            color=\"secondary_inverted\"\n            size=\"large\">\n            <ButtonText>\n              <Trans>Find accounts to follow</Trans>\n            </ButtonText>\n            <ButtonIcon icon={ChevronRightIcon} />\n          </Button>\n        </View>\n\n        <Text type=\"xl-medium\" style={[s.textCenter, pal.text, s.mt20]}>\n          <Trans>You can also discover new Custom Feeds to follow.</Trans>\n        </Text>\n        <View style={[a.mt_md, a.align_center]}>\n          <Button\n            label={l`Discover new custom feeds`}\n            onPress={onPressDiscoverFeeds}\n            color=\"secondary_inverted\"\n            size=\"large\">\n            <ButtonText>\n              <Trans>Discover new custom feeds</Trans>\n            </ButtonText>\n            <ButtonIcon icon={ChevronRightIcon} />\n          </Button>\n        </View>\n      </View>\n    </View>\n  )\n}","file":"src/view/com/posts/FollowingEmptyState.tsx","kind":"component","line":17,"members":{"navigation":[20,20],"onPressDiscoverFeeds":[31,33],"onPressFindAccounts":[22,29],"pal":[19,19]},"supers":[]},"FollowingFeedAPI":{"alsoIn":["src/features/followingV2/home/api/following.ts"],"appearsIn":[["home","h-classes","Logic \u00b7 class diagram"],["home","h-sequence","Scroll the Following feed \u00b7 sequence"]],"code":"export class FollowingFeedAPI implements FeedAPI {\n  client: Client\n\n  constructor({client}: {client: Client}) {\n    this.client = client\n  }\n\n  async peekLatest(): Promise<app.bsky.feed.defs.FeedViewPost> {\n    const data = await this.client.call(app.bsky.feed.getTimeline, {\n      limit: 1,\n    })\n    return data.feed[0]\n  }\n\n  async fetch({\n    cursor,\n    limit,\n  }: {\n    cursor: string | undefined\n    limit: number\n  }): Promise<FeedAPIResponse> {\n    /*\n     * A failed request rejects rather than resolving, so the error propagates\n     * to the query and drives the feed error UI. The agent behaved the same\n     * way - its `success` flag was only ever true - so the empty-page branch\n     * this replaces was unreachable.\n     */\n    const data = await this.client.call(app.bsky.feed.getTimeline, {\n      cursor,\n      limit,\n    })\n    return {\n      cursor: data.cursor,\n      feed: data.feed,\n    }\n  }\n}","file":"src/lib/api/feed/following.ts","kind":"class","line":6,"members":{"client":[7,7],"constructor":[9,11],"fetch":[20,41],"peekLatest":[13,18]},"supers":["FeedAPI"]},"HomeFeedAPI":{"alsoIn":["src/features/followingV2/home/api/home.ts"],"appearsIn":[["home","h-classes","Logic \u00b7 class diagram"]],"code":"export class HomeFeedAPI implements FeedAPI {\n  client: Client\n  following: FollowingFeedAPI\n  discover: CustomFeedAPI\n  usingDiscover = false\n  itemCursor = 0\n  userInterests?: string\n\n  constructor({\n    userInterests,\n    client,\n  }: {\n    userInterests?: string\n    client: Client\n  }) {\n    this.client = client\n    this.following = new FollowingFeedAPI({client})\n    this.discover = new CustomFeedAPI({\n      client,\n      feedParams: {feed: PROD_DEFAULT_FEED('whats-hot') as AtUriString},\n    })\n    this.userInterests = userInterests\n  }\n\n  reset() {\n    this.following = new FollowingFeedAPI({client: this.client})\n    this.discover = new CustomFeedAPI({\n      client: this.client,\n      feedParams: {feed: PROD_DEFAULT_FEED('whats-hot') as AtUriString},\n      userInterests: this.userInterests,\n    })\n    this.usingDiscover = false\n    this.itemCursor = 0\n  }\n\n  async peekLatest(): Promise<app.bsky.feed.defs.FeedViewPost> {\n    if (this.usingDiscover) {\n      return this.discover.peekLatest()\n    }\n    return this.following.peekLatest()\n  }\n\n  async fetch({\n    cursor,\n    limit,\n  }: {\n    cursor: string | undefined\n    limit: number\n  }): Promise<FeedAPIResponse> {\n    if (!cursor) {\n      this.reset()\n    }\n\n    let returnCursor\n    let posts: app.bsky.feed.defs.FeedViewPost[] = []\n\n    if (!this.usingDiscover) {\n      const res = await this.following.fetch({cursor, limit})\n      returnCursor = res.cursor\n      posts = posts.concat(res.feed)\n      if (!returnCursor) {\n        cursor = ''\n        posts.push(FALLBACK_MARKER_POST)\n        this.usingDiscover = true\n      }\n    }\n\n    if (this.usingDiscover && !__DEV__) {\n      const res = await this.discover.fetch({cursor, limit})\n      returnCursor = res.cursor\n      posts = posts.concat(res.feed)\n    }\n\n    return {\n      cursor: returnCursor,\n      feed: posts,\n    }\n  }\n}","file":"src/lib/api/feed/home.ts","kind":"class","line":36,"members":{"client":[37,37],"constructor":[44,58],"discover":[39,39],"fetch":[78,113],"following":[38,38],"itemCursor":[41,41],"peekLatest":[71,76],"reset":[60,69],"userInterests":[42,42],"usingDiscover":[40,40]},"supers":["FeedAPI"]},"HomeHeader":{"appearsIn":[["home","h-widgets","Screen \u00b7 component composition"]],"code":"export function HomeHeader(\n  props: RenderTabBarFnProps & {\n    testID?: string\n    onPressSelected: () => void\n    feeds: Pick<FeedSourceInfo, 'displayName' | 'uri'>[]\n  },\n) {\n  const {feeds, onSelect: onSelectProp} = props\n  const {hasSession} = useSession()\n  const {t: l, i18n} = useLingui()\n  const navigation = useNavigation<NavigationProp>()\n\n  const hasPinnedCustom = useMemo<boolean>(() => {\n    if (!hasSession) return false\n    return feeds.some(tab => {\n      const isFollowing = tab.uri === TIMELINE_SAVED_FEED.value\n      return !isFollowing\n    })\n  }, [feeds, hasSession])\n\n  const items = useMemo(() => {\n    const pinnedNames = feeds.map(f => getLocalizedFeedName(f, i18n))\n    if (!hasPinnedCustom) {\n      return pinnedNames.concat(l`Feeds \u2728`)\n    }\n    return pinnedNames\n  }, [i18n, l, hasPinnedCustom, feeds])\n\n  const onPressFeedsLink = useCallback(() => {\n    navigation.navigate('Feeds')\n  }, [navigation])\n\n  const onSelect = useCallback(\n    (index: number) => {\n      if (!hasPinnedCustom && index === items.length - 1) {\n        onPressFeedsLink()\n      } else if (onSelectProp) {\n        onSelectProp(index)\n      }\n    },\n    [items.length, onPressFeedsLink, onSelectProp, hasPinnedCustom],\n  )\n\n  return (\n    <HomeHeaderLayout tabBarAnchor={props.tabBarAnchor}>\n      <TabBar\n        key={items.join(',')}\n        onPressSelected={props.onPressSelected}\n        selectedPage={props.selectedPage}\n        onSelect={onSelect}\n        testID={props.testID}\n        items={items}\n        dragProgress={props.dragProgress}\n        dragState={props.dragState}\n        transparent\n      />\n    </HomeHeaderLayout>\n  )\n}","file":"src/view/com/home/HomeHeader.tsx","kind":"component","line":14,"members":{"hasPinnedCustom":[26,32],"items":[34,40],"navigation":[24,24],"onPressFeedsLink":[42,44],"onSelect":[46,55]},"supers":[]},"HomeScreenReady":{"alsoIn":["src/features/followingV2/home/Home.tsx"],"appearsIn":[["home","h-classes","Logic \u00b7 class diagram"],["home","h-widgets","Screen \u00b7 component composition"],["home","h-sequence","Scroll the Following feed \u00b7 sequence"]],"code":"function HomeScreenReady({\n  preferences,\n  pinnedFeedInfos,\n}: Props & {\n  preferences: UsePreferencesQueryResponse\n  pinnedFeedInfos: SavedFeedSourceInfo[]\n}) {\n  const {i18n} = useLingui()\n  const ax = useAnalytics()\n  const allFeeds = useMemo(\n    () => pinnedFeedInfos.map(f => f.feedDescriptor),\n    [pinnedFeedInfos],\n  )\n  const maybeRawSelectedFeed: FeedDescriptor | undefined =\n    useSelectedFeed() ?? allFeeds[0]\n  const setSelectedFeed = useSetSelectedFeed()\n  const maybeFoundIndex = allFeeds.indexOf(maybeRawSelectedFeed)\n  const selectedIndex = Math.max(0, maybeFoundIndex)\n  const maybeSelectedFeed: FeedDescriptor | undefined = allFeeds[selectedIndex]\n  const selectedFeedInfo = pinnedFeedInfos[selectedIndex]\n  const requestNotificationsPermission = useRequestNotificationsPermission()\n\n  useSetTitle(selectedFeedInfo && getLocalizedFeedName(selectedFeedInfo, i18n))\n  useOTAUpdates()\n\n  useEffect(() => {\n    void requestNotificationsPermission('Home')\n  }, [requestNotificationsPermission])\n\n  const pagerRef = useRef<PagerRef>(null)\n  const lastPagerReportedIndexRef = useRef(selectedIndex)\n  useLayoutEffect(() => {\n    // Since the pager is not a controlled component, adjust it imperatively\n    // if the selected index gets out of sync with what it last reported.\n    // This is supposed to only happen on the web when you use the right nav.\n    if (selectedIndex !== lastPagerReportedIndexRef.current) {\n      lastPagerReportedIndexRef.current = selectedIndex\n      pagerRef.current?.setPage(selectedIndex)\n    }\n  }, [selectedIndex])\n\n  const {hasSession} = useSession()\n  const headerMode = useHomeHeaderMode()\n  const showHeader = useCallback(() => {\n    'worklet'\n    headerMode.set(\n      withSpring(0, {\n        ...Reanimated3DefaultSpringConfig,\n        overshootClamping: true,\n      }),\n    )\n  }, [headerMode])\n\n  useFocusEffect(\n    useCallback(() => {\n      return () => showHeader()\n    }, [showHeader]),\n  )\n\n  useFocusEffect(\n    useNonReactiveCallback(() => {\n      if (maybeSelectedFeed) {\n        ax.metric('home:feedDisplayed', {\n          index: selectedIndex,\n          feedType: maybeSelectedFeed.split('|')[0],\n          feedUrl: maybeSelectedFeed,\n          reason: 'focus',\n        })\n      }\n    }),\n  )\n\n  const onPageSelected = useCallback(\n    (index: number) => {\n      showHeader()\n      const maybeFeed = allFeeds[index]\n\n      // Mutate the ref before setting state to avoid the imperative syncing effect\n      // above from starting a loop on Android when swiping back and forth.\n      lastPagerReportedIndexRef.current = index\n      setSelectedFeed(maybeFeed)\n\n      if (maybeFeed) {\n        ax.metric('home:feedDisplayed', {\n          index,\n          feedType: maybeFeed.split('|')[0],\n          feedUrl: maybeFeed,\n        })\n      }\n    },\n    [ax, setSelectedFeed, showHeader, allFeeds],\n  )\n\n  const onPressSelected = useCallback(() => {\n    emitSoftReset()\n  }, [])\n\n  const onPageScrollStateChanged = useCallback(\n    (state: 'idle' | 'dragging' | 'settling') => {\n      'worklet'\n      if (state === 'dragging') {\n        showHeader()\n      }\n    },\n    [showHeader],\n  )\n\n  const [demoMode] = useDemoMode()\n\n  const renderTabBar = useCallback(\n    (props: RenderTabBarFnProps) => {\n      if (demoMode) {\n        return (\n          <HomeHeader\n            key=\"FEEDS_TAB_BAR\"\n            {...props}\n            testID=\"homeScreenFeedTabs\"\n            onPressSelected={onPressSelected}\n            feeds={[\n              {\n                displayName: 'Following',\n                uri: TIMELINE_SAVED_FEED.value,\n              },\n              {displayName: 'Discover', uri: DISCOVER_FEED_URI},\n            ]}\n          />\n        )\n      }\n      return (\n        <HomeHeader\n          key=\"FEEDS_TAB_BAR\"\n          {...props}\n          testID=\"homeScreenFeedTabs\"\n          onPressSelected={onPressSelected}\n          feeds={pinnedFeedInfos}\n        />\n      )\n    },\n    [onPressSelected, pinnedFeedInfos, demoMode],\n  )\n\n  const renderFollowingEmptyState = useCallback(() => {\n    return <FollowingEmptyState />\n  }, [])\n\n  const renderCustomFeedEmptyState = useCallback(() => {\n    return <CustomFeedEmptyState />\n  }, [])\n\n  const homeFeedParams = useMemo<FeedParams>(() => {\n    return {\n      mergeFeedEnabled: Boolean(preferences.feedViewPrefs.lab_mergeFeedEnabled),\n      mergeFeedSources: preferences.feedViewPrefs.lab_mergeFeedEnabled\n        ? preferences.savedFeeds\n            .filter(f => f.type === 'feed' || f.type === 'list')\n            .map(f => f.value)\n        : [],\n    }\n  }, [preferences])\n\n  if (demoMode) {\n    return (\n      <Pager\n        ref={pagerRef}\n        testID=\"homeScreen\"\n        onPageSelected={onPageSelected}\n        renderTabBar={renderTabBar}\n        initialPage={selectedIndex}>\n        <FeedPage\n          testID=\"demoFeedPage\"\n          isPageFocused\n          isPageAdjacent={false}\n          feed=\"demo\"\n          renderEmptyState={renderCustomFeedEmptyState}\n          feedInfo={pinnedFeedInfos[0]}\n        />\n        <FeedPage\n          testID=\"customFeedPage\"\n          isPageFocused\n          isPageAdjacent={false}\n          feed={`feedgen|${PROD_DEFAULT_FEED('whats-hot')}`}\n          renderEmptyState={renderCustomFeedEmptyState}\n          feedInfo={pinnedFeedInfos[0]}\n        />\n      </Pager>\n    )\n  }\n\n  return hasSession ? (\n    <Pager\n      key={allFeeds.join(',')}\n      ref={pagerRef}\n      testID=\"homeScreen\"\n      initialPage={selectedIndex}\n      onPageSelected={onPageSelected}\n      onPageScrollStateChanged={onPageScrollStateChanged}\n      renderTabBar={renderTabBar}>\n      {pinnedFeedInfos.length ? (\n        pinnedFeedInfos.map((feedInfo, index) => {\n          const feed = feedInfo.feedDescriptor\n          if (feed === 'following') {\n            return (\n              <FeedPage\n                key={feed}\n                testID=\"followingFeedPage\"\n                isPageFocused={maybeSelectedFeed === feed}\n                isPageAdjacent={Math.abs(selectedIndex - index) === 1}\n                feed={feed}\n                feedParams={homeFeedParams}\n                renderEmptyState={renderFollowingEmptyState}\n                renderEndOfFeed={FollowingEndOfFeed}\n                feedInfo={feedInfo}\n              />\n            )\n          }\n          const savedFeedConfig = feedInfo.savedFeed\n          return (\n            <FeedPage\n              key={feed}\n              testID=\"customFeedPage\"\n              isPageFocused={maybeSelectedFeed === feed}\n              isPageAdjacent={Math.abs(selectedIndex - index) === 1}\n              feed={feed}\n              renderEmptyState={renderCustomFeedEmptyState}\n              savedFeedConfig={savedFeedConfig}\n              feedInfo={feedInfo}\n            />\n          )\n        })\n      ) : (\n        <NoFeedsPinned preferences={preferences} />\n      )}\n    </Pager>\n  ) : (\n    <Pager\n      testID=\"homeScreen\"\n      onPageSelected={onPageSelected}\n      onPageScrollStateChanged={onPageScrollStateChanged}\n      renderTabBar={renderTabBar}>\n      <FeedPage\n        testID=\"customFeedPage\"\n        isPageFocused\n        isPageAdjacent={false}\n        feed={`feedgen|${PROD_DEFAULT_FEED('whats-hot')}`}\n        renderEmptyState={renderCustomFeedEmptyState}\n        feedInfo={pinnedFeedInfos[0]}\n      />\n    </Pager>\n  )\n}","file":"src/view/screens/Home.tsx","kind":"component","line":116,"members":{"allFeeds":[125,128],"ax":[124,124],"demoMode":[223,223],"headerMode":[158,158],"homeFeedParams":[265,274],"lastPagerReportedIndexRef":[146,146],"onPageScrollStateChanged":[213,221],"onPageSelected":[188,207],"onPressSelected":[209,211],"pagerRef":[145,145],"pinnedFeedInfos":[116,122],"preferences":[116,122],"renderCustomFeedEmptyState":[261,263],"renderFollowingEmptyState":[257,259],"renderTabBar":[225,255],"requestNotificationsPermission":[136,136],"setSelectedFeed":[131,131],"showHeader":[159,167]},"supers":[]},"ListFeedAPI":{"alsoIn":["src/features/followingV2/home/api/list.ts"],"appearsIn":[["home","h-classes","Logic \u00b7 class diagram"]],"code":"export class ListFeedAPI implements FeedAPI {\n  client: Client\n  params: GetListFeedParams\n\n  constructor({\n    client,\n    feedParams,\n  }: {\n    client: Client\n    feedParams: GetListFeedParams\n  }) {\n    this.client = client\n    this.params = feedParams\n  }\n\n  async peekLatest(): Promise<app.bsky.feed.defs.FeedViewPost> {\n    const data = await this.client.call(app.bsky.feed.getListFeed, {\n      ...this.params,\n      limit: 1,\n    })\n    return data.feed[0]\n  }\n\n  async fetch({\n    cursor,\n    limit,\n  }: {\n    cursor: string | undefined\n    limit: number\n  }): Promise<FeedAPIResponse> {\n    /*\n     * A failed request rejects rather than resolving, so the error propagates\n     * to the query and drives the feed error UI. The agent behaved the same\n     * way - its `success` flag was only ever true - so the empty-page branch\n     * this replaces was unreachable.\n     */\n    const data = await this.client.call(app.bsky.feed.getListFeed, {\n      ...this.params,\n      cursor,\n      limit,\n    })\n    return {\n      cursor: data.cursor,\n      feed: data.feed,\n    }\n  }\n}","file":"src/lib/api/feed/list.ts","kind":"class","line":10,"members":{"client":[11,11],"constructor":[14,23],"fetch":[33,55],"params":[12,12],"peekLatest":[25,31]},"supers":["FeedAPI"]},"MergeFeedAPI":{"appearsIn":[["home","h-classes","Logic \u00b7 class diagram"]],"code":"export class MergeFeedAPI implements FeedAPI {\n  userInterests?: string\n  client: Client\n  params: FeedParams\n  feedTuners: FeedTunerFn[]\n  following: MergeFeedSource_Following\n  customFeeds: MergeFeedSource_Custom[] = []\n  feedCursor = 0\n  itemCursor = 0\n  sampleCursor = 0\n\n  constructor({\n    client,\n    feedParams,\n    feedTuners,\n    userInterests,\n  }: {\n    client: Client\n    feedParams: FeedParams\n    feedTuners: FeedTunerFn[]\n    userInterests?: string\n  }) {\n    this.client = client\n    this.params = feedParams\n    this.feedTuners = feedTuners\n    this.userInterests = userInterests\n    this.following = new MergeFeedSource_Following({\n      client: this.client,\n      feedTuners: this.feedTuners,\n    })\n  }\n\n  reset() {\n    this.following = new MergeFeedSource_Following({\n      client: this.client,\n      feedTuners: this.feedTuners,\n    })\n    this.customFeeds = []\n    this.feedCursor = 0\n    this.itemCursor = 0\n    this.sampleCursor = 0\n    if (this.params.mergeFeedSources) {\n      this.customFeeds = shuffle(\n        this.params.mergeFeedSources.map(\n          feedUri =>\n            new MergeFeedSource_Custom({\n              client: this.client,\n              feedUri,\n              feedTuners: this.feedTuners,\n              userInterests: this.userInterests,\n            }),\n        ),\n      )\n    } else {\n      this.customFeeds = []\n    }\n  }\n\n  async peekLatest(): Promise<app.bsky.feed.defs.FeedViewPost> {\n    const data = await this.client.call(app.bsky.feed.getTimeline, {\n      limit: 1,\n    })\n    return data.feed[0]\n  }\n\n  async fetch({\n    cursor,\n    limit,\n  }: {\n    cursor: string | undefined\n    limit: number\n  }): Promise<FeedAPIResponse> {\n    if (!cursor) {\n      this.reset()\n    }\n\n    const promises = []\n\n    // always keep following topped up while the source has another page\n    if (this.following.hasMore && this.following.numReady < limit) {\n      await this.following.fetchNext(60)\n    }\n\n    // pick the next feeds to sample from\n    const feeds = this.customFeeds.slice(this.feedCursor, this.feedCursor + 3)\n    this.feedCursor += 3\n    if (this.feedCursor > this.customFeeds.length) {\n      this.feedCursor = 0\n    }\n\n    // top up the feeds\n    const outOfFollows =\n      !this.following.hasMore && this.following.numReady < limit\n    if (this.params.mergeFeedEnabled || outOfFollows) {\n      for (const feed of feeds) {\n        if (feed.hasMore && feed.numReady < 5) {\n          promises.push(feed.fetchNext(10))\n        }\n      }\n    }\n\n    // wait for requests (all capped at a fixed timeout)\n    await Promise.all(promises)\n\n    // assemble a response by sampling from feeds with content\n    const posts: app.bsky.feed.defs.FeedViewPost[] = []\n    while (posts.length < limit) {\n      let slice = this.sampleItem()\n      if (slice[0]) {\n        posts.push(slice[0])\n      } else {\n        break\n      }\n    }\n\n    const hasMore =\n      this.following.hasMore ||\n      this.following.numReady > 0 ||\n      this.customFeeds.some(feed => feed.hasMore || feed.numReady > 0)\n    return {\n      cursor: hasMore ? String(this.itemCursor) : undefined,\n      feed: posts,\n    }\n  }\n\n  sampleItem() {\n    const i = this.itemCursor++\n    const candidateFeeds = this.customFeeds.filter(f => f.numReady > 0)\n    const canSample = candidateFeeds.length > 0\n    const hasFollowsReady = this.following.numReady > 0\n    const hasFollows = this.following.hasMore || hasFollowsReady\n\n    // this condition establishes the frequency that custom feeds are woven into follows\n    const shouldSample =\n      this.params.mergeFeedEnabled &&\n      i >= 15 &&\n      candidateFeeds.length >= 2 &&\n      (i % 4 === 0 || i % 5 === 0)\n\n    if (!canSample && !hasFollows) {\n      // no data available\n      return []\n    }\n    if (shouldSample || !hasFollows) {\n      // time to sample, or the user isnt following anybody\n      return candidateFeeds[this.sampleCursor++ % candidateFeeds.length].take(1)\n    }\n    if (!hasFollowsReady) {\n      // stop here so more follows can be fetched\n      return []\n    }\n    // provide follow\n    return this.following.take(1)\n  }\n}","file":"src/lib/api/feed/merge.ts","kind":"class","line":37,"members":{"client":[39,39],"constructor":[48,67],"customFeeds":[43,43],"feedCursor":[44,44],"feedTuners":[41,41],"fetch":[102,160],"following":[42,42],"itemCursor":[45,45],"params":[40,40],"peekLatest":[95,100],"reset":[69,93],"sampleCursor":[46,46],"sampleItem":[162,190],"userInterests":[38,38]},"supers":["FeedAPI"]},"Pager":{"alsoIn":["src/view/com/pager/Pager.web.tsx"],"appearsIn":[["home","h-widgets","Screen \u00b7 component composition"]],"code":"export function Pager({\n  ref,\n  children,\n  initialPage = 0,\n  renderTabBar,\n  onPageSelected: parentOnPageSelected,\n  onTabPressed: parentOnTabPressed,\n  onPageScrollStateChanged: parentOnPageScrollStateChanged,\n  testID,\n}: React.PropsWithChildren<Props>) {\n  const [selectedPage, setSelectedPage] = useState(initialPage)\n  const pagerView = useRef<PagerView>(null)\n\n  const [isIdle, setIsIdle] = useState(true)\n  const setDrawerSwipeDisabled = useSetDrawerSwipeDisabled()\n  useFocusEffect(\n    useCallback(() => {\n      const canSwipeDrawer = selectedPage === 0 && isIdle\n      setDrawerSwipeDisabled(!canSwipeDrawer)\n      return () => {\n        setDrawerSwipeDisabled(false)\n      }\n    }, [setDrawerSwipeDisabled, selectedPage, isIdle]),\n  )\n\n  useImperativeHandle(ref, () => ({\n    setPage: (index: number) => {\n      pagerView.current?.setPage(index)\n    },\n  }))\n\n  const onPageSelectedJSThread = useCallback(\n    (nextPosition: number) => {\n      setSelectedPage(nextPosition)\n      parentOnPageSelected?.(nextPosition)\n    },\n    [setSelectedPage, parentOnPageSelected],\n  )\n\n  const onTabBarSelect = useCallback(\n    (index: number) => {\n      parentOnTabPressed?.(index)\n      pagerView.current?.setPage(index)\n    },\n    [pagerView, parentOnTabPressed],\n  )\n\n  const dragState = useSharedValue<'idle' | 'settling' | 'dragging'>('idle')\n  const dragProgress = useSharedValue(selectedPage)\n  const didInit = useSharedValue(false)\n  const pagerFade = usePagerFade(dragProgress)\n  const handlePageScroll = usePagerHandlers({\n    onPageScroll(e: PagerViewOnPageScrollEventData) {\n      'worklet'\n      if (didInit.get() === false) {\n        // On iOS, there's a spurious scroll event with 0 position\n        // even if a different page was supplied as the initial page.\n        // Ignore it and wait for the first confirmed selection instead.\n        return\n      }\n      dragProgress.set(e.offset + e.position)\n    },\n    onPageScrollStateChanged(e: PageScrollStateChangedNativeEventData) {\n      'worklet'\n      scheduleOnRN(setIsIdle, e.pageScrollState === 'idle')\n      if (e.pageScrollState === 'idle') {\n        /*\n         * Adjacent pages stay attached to the window, so their videos are not\n         * torn down when paged away from. Re-pick the active video once the\n         * pager settles so the one on the old page stops.\n         */\n        scheduleOnRN(updateActiveVideoViewAsync)\n      }\n      if (dragState.get() === 'idle' && e.pageScrollState === 'settling') {\n        // This is a programmatic scroll on Android.\n        // Stay \"idle\" to match iOS and avoid confusing downstream code.\n        return\n      }\n      dragState.set(e.pageScrollState)\n      parentOnPageScrollStateChanged?.(e.pageScrollState)\n    },\n    onPageSelected(e: PagerViewOnPageSelectedEventData) {\n      'worklet'\n      if (!didInit.get()) {\n        dragProgress.set(e.position)\n      }\n      didInit.set(true)\n      scheduleOnRN(onPageSelectedJSThread, e.position)\n    },\n  })\n\n  return (\n    <View testID={testID} style={[a.flex_1, native(a.overflow_hidden)]}>\n      {renderTabBar({\n        selectedPage,\n        onSelect: onTabBarSelect,\n        dragProgress,\n        dragState,\n      })}\n      <DrawerGestureRequireFail>\n        <MemoizedAnimatedPagerView\n          ref={pagerView}\n          style={[a.flex_1, pagerFade.style]}\n          initialPage={initialPage}\n          onLayout={pagerFade.onLayout}\n          onPageScroll={handlePageScroll}>\n          {children}\n        </MemoizedAnimatedPagerView>\n      </DrawerGestureRequireFail>\n    </View>\n  )\n}","file":"src/view/com/pager/Pager.tsx","kind":"component","line":65,"members":{"children":[65,74],"didInit":[114,114],"dragProgress":[113,113],"dragState":[112,112],"handlePageScroll":[116,154],"initialPage":[65,74],"isIdle":[78,78],"onPageSelectedJSThread":[96,102],"onTabBarSelect":[104,110],"pagerFade":[115,115],"pagerView":[76,76],"parentOnPageScrollStateChanged":[65,74],"parentOnPageSelected":[65,74],"parentOnTabPressed":[65,74],"ref":[65,74],"renderTabBar":[65,74],"selectedPage":[75,75],"setDrawerSwipeDisabled":[79,79],"testID":[65,74]},"supers":[]},"PostFeed":{"alsoIn":["src/features/followingV2/home/PostFeed.tsx"],"appearsIn":[["home","h-classes","Logic \u00b7 class diagram"],["home","h-widgets","Screen \u00b7 component composition"],["home","h-sequence","Scroll the Following feed \u00b7 sequence"],["index","h-screens","Screens \u00b7 how the user moves"],["profile","h-classes","Logic \u00b7 class diagram"]],"code":"let PostFeed = ({\n  feed,\n  description,\n  feedParams,\n  ignoreFilterFor,\n  style,\n  enabled,\n  pollInterval,\n  disablePoll,\n  scrollElRef,\n  onScrolledDownChange,\n  onHasNew,\n  renderEmptyState,\n  renderEndOfFeed,\n  testID,\n  headerOffset = 0,\n  progressViewOffset,\n  desktopFixedHeightOffset,\n  ListHeaderComponent,\n  extraData,\n  savedFeedConfig,\n  initialNumToRender: initialNumToRenderOverride,\n  isVideoFeed = false,\n  ref,\n}: {\n  feed: FeedDescriptor\n  description?: RichTextType\n  feedParams?: FeedParams\n  ignoreFilterFor?: string\n  style?: StyleProp<ViewStyle>\n  enabled?: boolean\n  pollInterval?: number\n  disablePoll?: boolean\n  scrollElRef?: ListRef\n  onHasNew?: (v: boolean) => void\n  onScrolledDownChange?: (isScrolledDown: boolean) => void\n  renderEmptyState: () => React.ReactElement\n  renderEndOfFeed?: () => React.ReactElement\n  testID?: string\n  headerOffset?: number\n  progressViewOffset?: number\n  desktopFixedHeightOffset?: number\n  ListHeaderComponent?: () => React.ReactElement\n  extraData?: Record<string, unknown>\n  savedFeedConfig?: app.bsky.actor.defs.SavedFeed\n  initialNumToRender?: number\n  isVideoFeed?: boolean\n  lastFetchDate?: () => number\n  ref?: React.Ref<PostFeedRef>\n}): React.ReactNode => {\n  const ax = useAnalytics()\n  const t = useTheme()\n  const {t: l} = useLingui()\n  const queryClient = useQueryClient()\n  const {currentAccount, hasSession} = useSession()\n  const initialNumToRender = useInitialNumToRender()\n  const feedFeedback = useFeedFeedbackContext()\n  const [isPTRing, setIsPTRing] = useState(false)\n  // eslint-disable-next-line react-hooks/purity\n  const lastFetchRef = useRef<number>(Date.now())\n  const [feedType, feedUriOrActorDid, feedTab] = feed.split('|')\n  const videoGridColumns = useVideoGridColumns()\n  const {rightNavVisible} = useLayoutBreakpoints()\n  const areVideoFeedsEnabled = IS_NATIVE\n\n  const trendingIndices = ax.features.getValue(\n    ax.features.TrendingDiscoverValues,\n    {\n      topics: 5,\n      accounts: 15,\n      videos: 30,\n    },\n  )\n\n  const [hasPressedShowLessUris, setHasPressedShowLessUris] = useState(\n    () => new Set<string>(),\n  )\n  const onPressShowLess = useCallback(\n    (interaction: app.bsky.feed.defs.Interaction) => {\n      if (interaction.item) {\n        const uri = interaction.item\n        setHasPressedShowLessUris(prev => new Set([...prev, uri]))\n        LayoutAnimation.configureNext(LayoutAnimation.Presets.easeInEaseOut)\n      }\n    },\n    [],\n  )\n\n  const feedCacheKey = feedParams?.feedCacheKey\n  const opts = useMemo(\n    () => ({enabled, ignoreFilterFor}),\n    [enabled, ignoreFilterFor],\n  )\n  const {\n    data,\n    isFetching,\n    isFetched,\n    isError,\n    error,\n    refetch,\n    hasNextPage,\n    isPageFillLimited,\n    isFetchingNextPage,\n    fetchNextPage,\n  } = usePostFeedQuery(feed, feedParams, opts)\n  const lastFetchedAt = data?.pages[0].fetchedAt\n  const isEmpty = useMemo(\n    () => !isFetching && !data?.pages?.some(page => page.slices.length),\n    [isFetching, data],\n  )\n\n  useEffect(() => {\n    if (lastFetchedAt) {\n      lastFetchRef.current = lastFetchedAt\n    }\n  }, [lastFetchedAt])\n\n  const checkForNew = useNonReactiveCallback(async () => {\n    if (!data?.pages[0] || isFetching || !onHasNew || !enabled || disablePoll) {\n      return\n    }\n\n    // Discover always has fresh content\n    if (feedUriOrActorDid === DISCOVER_FEED_URI) {\n      return onHasNew(true)\n    }\n\n    try {\n      if (await pollLatest(data.pages[0])) {\n        if (isEmpty) {\n          void refetch()\n        } else {\n          onHasNew(true)\n        }\n      }\n    } catch (e) {\n      if (!isNetworkError(e)) {\n        logger.warn('Poll latest failed', {feed, message: String(e)})\n      }\n    }\n  })\n\n  const isScrolledDownRef = useRef(false)\n  const handleScrolledDownChange = (isScrolledDown: boolean) => {\n    isScrolledDownRef.current = isScrolledDown\n    onScrolledDownChange?.(isScrolledDown)\n  }\n\n  const myDid = currentAccount?.did || ''\n  const onPostCreated = useCallback(() => {\n    // NOTE\n    // only invalidate if at the top of the feed\n    // changing content when scrolled can trigger some UI freakouts on iOS and android\n    // -sfn\n    if (\n      !isScrolledDownRef.current &&\n      (feed === 'following' ||\n        feed === `author|${myDid}|posts_and_author_threads`)\n    ) {\n      void queryClient.invalidateQueries({queryKey: RQKEY(feed)})\n    }\n  }, [queryClient, feed, myDid])\n  useEffect(() => {\n    return listenPostCreated(onPostCreated)\n  }, [onPostCreated])\n\n  useEffect(() => {\n    if (enabled && !disablePoll) {\n      const timeSinceFirstLoad = Date.now() - lastFetchRef.current\n      if (isEmpty || timeSinceFirstLoad > CHECK_LATEST_AFTER) {\n        // check for new on enable (aka on focus)\n        void checkForNew()\n      }\n    }\n  }, [enabled, isEmpty, disablePoll, checkForNew])\n\n  useEffect(() => {\n    let cleanup1: () => void | undefined, cleanup2: () => void | undefined\n    const subscription = AppState.addEventListener('change', nextAppState => {\n      // check for new on app foreground\n      if (nextAppState === 'active') {\n        void checkForNew()\n      }\n    })\n    cleanup1 = () => subscription.remove()\n    if (pollInterval) {\n      // check for new on interval\n      const i = setInterval(() => {\n        void checkForNew()\n      }, pollInterval)\n      cleanup2 = () => clearInterval(i)\n    }\n    return () => {\n      cleanup1?.()\n      cleanup2?.()\n    }\n  }, [pollInterval, checkForNew])\n\n  const followProgressGuide = useProgressGuide('follow-10')\n  const followAndLikeProgressGuide = useProgressGuide('like-10-and-follow-7')\n\n  const showProgressInterstitial =\n    (followProgressGuide || followAndLikeProgressGuide) && !rightNavVisible\n\n  const {trendingVideoDisabled} = useTrendingSettings()\n\n  const ageAssuranceBannerState = useAgeAssuranceBannerState()\n  const selectedFeed = useSelectedFeed()\n  /**\n   * Cached value of whether the current feed was selected at startup. We don't\n   * want this to update when user swipes.\n   */\n  // oxlint-disable-next-line react/hook-use-state\n  const [isCurrentFeedAtStartupSelected] = useState(selectedFeed === feed)\n\n  const blockedOrMutedAuthors = usePostAuthorShadowFilter(\n    // author feeds have their own handling\n    feed.startsWith('author|') ? undefined : data?.pages,\n  )\n\n  const feedItems: FeedRow[] = useMemo(() => {\n    // wraps a slice item, and replaces it with a showLessFollowup item\n    // if the user has pressed show less on it\n    const sliceItem = (row: Extract<FeedRow, {type: 'sliceItem'}>) => {\n      if (hasPressedShowLessUris.has(row.slice.items[row.indexInSlice]?.uri)) {\n        return {\n          type: 'showLessFollowup',\n          key: row.key,\n        } as const\n      } else {\n        return row\n      }\n    }\n\n    let feedKind: 'following' | 'discover' | 'profile' | 'thevids' | undefined\n    if (feedType === 'following') {\n      feedKind = 'following'\n    } else if (feedUriOrActorDid === DISCOVER_FEED_URI) {\n      feedKind = 'discover'\n    } else if (\n      feedType === 'author' &&\n      (feedTab === 'posts_and_author_threads' ||\n        feedTab === 'posts_with_replies' ||\n        feedTab === 'posts_and_replies_only')\n    ) {\n      feedKind = 'profile'\n    }\n\n    let arr: FeedRow[] = []\n    if (KNOWN_SHUTDOWN_FEEDS.includes(feedUriOrActorDid)) {\n      arr.push({\n        type: 'feedShutdownMsg',\n        key: 'feedShutdownMsg',\n      })\n    }\n    if (isFetched) {\n      if (isError && isEmpty) {\n        arr.push({\n          type: 'error',\n          key: 'error',\n        })\n      } else if (isEmpty) {\n        arr.push({\n          type: 'empty',\n          key: 'empty',\n        })\n      } else if (data) {\n        let sliceIndex = -1\n\n        if (isVideoFeed) {\n          const videos: {\n            item: FeedPostSliceItem\n            feedContext: string | undefined\n            reqId: string | undefined\n          }[] = []\n          for (const page of data.pages) {\n            for (const slice of page.slices) {\n              const item = slice.items.find(\n                item => item.uri === slice.feedPostUri,\n              )\n              if (\n                item &&\n                bsky.isType(app.bsky.embed.video.view, item.post.embed) &&\n                !blockedOrMutedAuthors.includes(item.post.author.did)\n              ) {\n                videos.push({\n                  item,\n                  feedContext: slice.feedContext,\n                  reqId: slice.reqId,\n                })\n              }\n            }\n          }\n\n          const rows: {\n            item: FeedPostSliceItem\n            feedContext: string | undefined\n            reqId: string | undefined\n          }[][] = []\n          for (let i = 0; i < videos.length; i++) {\n            const video = videos[i]\n            const item = video.item\n            const rowItem = {\n              item,\n              feedContext: video.feedContext,\n              reqId: video.reqId,\n            }\n            if (i % videoGridColumns === 0) {\n              rows.push([rowItem])\n            } else {\n              rows[rows.length - 1].push(rowItem)\n            }\n          }\n\n          for (const row of rows) {\n            sliceIndex++\n            arr.push({\n              type: 'videoGridRow',\n              key: row.map(r => r.item._reactKey).join('-'),\n              items: row.map(r => r.item),\n              sourceFeedUri: feedUriOrActorDid,\n              feedContexts: row.map(r => r.feedContext),\n              reqIds: row.map(r => r.reqId),\n            })\n          }\n        } else {\n          for (const page of data?.pages) {\n            for (const slice of page.slices) {\n              sliceIndex++\n\n              if (hasSession) {\n                if (feedKind === 'discover') {\n                  if (sliceIndex === 0) {\n                    if (showProgressInterstitial) {\n                      arr.push({\n                        type: 'interstitialProgressGuide',\n                        key: 'interstitial-' + sliceIndex + '-' + lastFetchedAt,\n                      })\n                    } else {\n                      /*\n                       * Only insert if Discover was the last selected feed at\n                       * startup, the progress guide isn't shown, and the\n                       * banner is eligible to be shown.\n                       */\n                      if (\n                        isCurrentFeedAtStartupSelected &&\n                        ageAssuranceBannerState.visible\n                      ) {\n                        arr.push({\n                          type: 'ageAssuranceBanner',\n                          key: 'ageAssuranceBanner-' + sliceIndex,\n                        })\n                      }\n                    }\n                    arr.push({\n                      type: 'liveEventFeedsAndTrendingBanner',\n                      key: 'liveEventFeedsAndTrendingBanner-' + sliceIndex,\n                    })\n                    // Show composer prompt for Discover and Following feeds\n                    if (\n                      hasSession &&\n                      (feedUriOrActorDid === DISCOVER_FEED_URI ||\n                        feed === 'following')\n                    ) {\n                      arr.push({\n                        type: 'composerPrompt',\n                        key: 'composerPrompt-' + sliceIndex,\n                      })\n                    }\n                  } else if (sliceIndex === trendingIndices.topics) {\n                    arr.push({\n                      type: 'interstitialFeedTrendingTopics',\n                      key: 'interstitialFeedTrendingTopics-' + sliceIndex,\n                      feedSliceIndex: sliceIndex,\n                    })\n                  } else if (sliceIndex === trendingIndices.videos) {\n                    if (areVideoFeedsEnabled && !trendingVideoDisabled) {\n                      arr.push({\n                        type: 'interstitialTrendingVideos',\n                        key: 'interstitial-' + sliceIndex + '-' + lastFetchedAt,\n                      })\n                    }\n                  } else if (sliceIndex === trendingIndices.accounts) {\n                    arr.push({\n                      type: 'interstitialFollows',\n                      key: 'interstitial-' + sliceIndex + '-' + lastFetchedAt,\n                    })\n                  }\n                } else if (feedKind === 'following') {\n                  if (sliceIndex === 0) {\n                    // Show composer prompt for Following feed\n                    if (hasSession) {\n                      arr.push({\n                        type: 'composerPrompt',\n                        key: 'composerPrompt-' + sliceIndex,\n                      })\n                    }\n                  }\n                } else if (feedKind === 'profile') {\n                  if (sliceIndex === 5) {\n                    arr.push({\n                      type: 'interstitialFollows',\n                      key: 'interstitial-' + sliceIndex + '-' + lastFetchedAt,\n                    })\n                  }\n                } else {\n                  /*\n                   * Only insert if this feed was the last selected feed at\n                   * startup and the banner is eligible to be shown.\n                   */\n                  if (sliceIndex === 0 && isCurrentFeedAtStartupSelected) {\n                    arr.push({\n                      type: 'ageAssuranceBanner',\n                      key: 'ageAssuranceBanner-' + sliceIndex,\n                    })\n                  }\n                }\n              }\n\n              if (slice.isFallbackMarker) {\n                arr.push({\n                  type: 'fallbackMarker',\n                  key:\n                    'sliceFallbackMarker-' + sliceIndex + '-' + lastFetchedAt,\n                })\n              } else if (\n                slice.items.some(item =>\n                  blockedOrMutedAuthors.includes(item.post.author.did),\n                )\n              ) {\n                // skip\n              } else if (slice.isIncompleteThread && slice.items.length >= 3) {\n                const beforeLast = slice.items.length - 2\n                const last = slice.items.length - 1\n                arr.push(\n                  sliceItem({\n                    type: 'sliceItem',\n                    key: slice.items[0]._reactKey,\n                    slice: slice,\n                    indexInSlice: 0,\n                    showReplyTo: false,\n                  }),\n                )\n                arr.push({\n                  type: 'sliceViewFullThread',\n                  key: slice._reactKey + '-viewFullThread',\n                  uri: slice.items[0].uri,\n                })\n                arr.push(\n                  sliceItem({\n                    type: 'sliceItem',\n                    key: slice.items[beforeLast]._reactKey,\n                    slice: slice,\n                    indexInSlice: beforeLast,\n                    showReplyTo:\n                      slice.items[beforeLast].parentAuthor?.did !==\n                      slice.items[beforeLast].post.author.did,\n                  }),\n                )\n                arr.push(\n                  sliceItem({\n                    type: 'sliceItem',\n                    key: slice.items[last]._reactKey,\n                    slice: slice,\n                    indexInSlice: last,\n                    showReplyTo: false,\n                  }),\n                )\n              } else {\n                for (let i = 0; i < slice.items.length; i++) {\n                  arr.push(\n                    sliceItem({\n                      type: 'sliceItem',\n                      key: slice.items[i]._reactKey,\n                      slice: slice,\n                      indexInSlice: i,\n                      showReplyTo: i === 0,\n                    }),\n                  )\n                }\n              }\n            }\n          }\n        }\n      }\n      if (isError && !isEmpty) {\n        arr.push({\n          type: 'loadMoreError',\n          key: 'loadMoreError',\n        })\n      }\n    } else {\n      if (isVideoFeed) {\n        arr.push({\n          type: 'videoGridRowPlaceholder',\n          key: 'videoGridRowPlaceholder',\n        })\n      } else {\n        arr.push({\n          type: 'loading',\n          key: 'loading',\n        })\n      }\n    }\n\n    if (description?.text) {\n      arr.unshift({\n        key: 'description',\n        type: 'description',\n        value: description,\n      })\n    }\n\n    return arr\n  }, [\n    description,\n    isFetched,\n    isError,\n    isEmpty,\n    lastFetchedAt,\n    data,\n    feed,\n    feedType,\n    feedUriOrActorDid,\n    feedTab,\n    hasSession,\n    showProgressInterstitial,\n    trendingVideoDisabled,\n    videoGridColumns,\n    isVideoFeed,\n    areVideoFeedsEnabled,\n    hasPressedShowLessUris,\n    ageAssuranceBannerState,\n    isCurrentFeedAtStartupSelected,\n    blockedOrMutedAuthors,\n    trendingIndices,\n  ])\n\n  // events\n  // =\n  //\n\n  const refreshFeed = async () => {\n    if (!enabled) return\n\n    ax.metric('feed:refresh', {\n      feedType: feedType,\n      feedUrl: feed,\n      reason: 'pull-to-refresh',\n    })\n    try {\n      await truncateAndInvalidate(queryClient, RQKEY(feed, feedParams))\n      if (onHasNew) {\n        onHasNew(false)\n      }\n    } catch (err) {\n      logger.error('Failed to refresh posts feed', {message: err})\n    }\n  }\n\n  const onRefresh = async () => {\n    setIsPTRing(true)\n    await refreshFeed()\n    setIsPTRing(false)\n  }\n\n  useImperativeHandle(ref, () => ({\n    refreshFeed,\n  }))\n\n  const onEndReached = useCallback(async () => {\n    if (isFetching || !hasNextPage || isError) return\n\n    ax.metric('feed:endReached', {\n      feedType: feedType,\n      feedUrl: feed,\n      itemCount: feedItems.length,\n    })\n    try {\n      await fetchNextPage()\n    } catch (err) {\n      logger.error('Failed to load more posts', {message: err})\n    }\n  }, [\n    ax,\n    isFetching,\n    hasNextPage,\n    isError,\n    fetchNextPage,\n    feed,\n    feedType,\n    feedItems.length,\n  ])\n\n  const onPressTryAgain = useCallback(() => {\n    void refetch()\n    onHasNew?.(false)\n  }, [refetch, onHasNew])\n\n  const onPressRetryLoadMore = useCallback(() => {\n    void fetchNextPage()\n  }, [fetchNextPage])\n\n  // rendering\n  // =\n\n  const renderItem = useCallback(\n    ({item: row, index: rowIndex}: ListRenderItemInfo<FeedRow>) => {\n      if (row.type === 'empty') {\n        return isPageFillLimited ? <RepliesFeedLimited /> : renderEmptyState()\n      } else if (row.type === 'error') {\n        return (\n          <PostFeedErrorMessage\n            feedDesc={feed}\n            error={error ?? undefined}\n            onPressTryAgain={onPressTryAgain}\n            savedFeedConfig={savedFeedConfig}\n          />\n        )\n      } else if (row.type === 'loadMoreError') {\n        return (\n          <LoadMoreRetryBtn\n            label={l`There was an issue fetching posts. Tap here to try again.`}\n            onPress={onPressRetryLoadMore}\n          />\n        )\n      } else if (row.type === 'loading') {\n        return <PostFeedSkeleton />\n      } else if (row.type === 'feedShutdownMsg') {\n        return <FeedShutdownMsg feedUri={feedUriOrActorDid} />\n      } else if (row.type === 'description') {\n        return (\n          <RichText\n            value={row.value}\n            style={[\n              a.m_md,\n              a.text_md,\n              a.leading_snug,\n              t.atoms.text_contrast_high,\n            ]}\n          />\n        )\n      } else if (row.type === 'interstitialFollows') {\n        return <SuggestedFollows feed={feed} />\n      } else if (row.type === 'interstitialProgressGuide') {\n        return <ProgressGuide />\n      } else if (row.type === 'ageAssuranceBanner') {\n        return <AgeAssuranceDismissibleFeedBanner />\n      } else if (row.type === 'interstitialFeedTrendingTopics') {\n        return (\n          <FeedTrendingTopicsInterstitial feedSliceIndex={row.feedSliceIndex} />\n        )\n      } else if (row.type === 'liveEventFeedsAndTrendingBanner') {\n        return <DiscoverFeedLiveEventFeedsAndTrendingBanner />\n      } else if (row.type === 'composerPrompt') {\n        return <ComposerPrompt />\n      } else if (row.type === 'interstitialTrendingVideos') {\n        return <TrendingVideosInterstitial />\n      } else if (row.type === 'fallbackMarker') {\n        // HACK\n        // tell the user we fell back to discover\n        // see home.ts (feed api) for more info\n        // -prf\n        return <DiscoverFallbackHeader />\n      } else if (row.type === 'sliceItem') {\n        const slice = row.slice\n        const indexInSlice = row.indexInSlice\n        const item = slice.items[indexInSlice]\n        return (\n          <PostFeedItem\n            post={item.post}\n            record={item.record}\n            postNumbering={item.postNumbering}\n            reason={indexInSlice === 0 ? slice.reason : undefined}\n            feedContext={slice.feedContext}\n            reqId={slice.reqId}\n            moderation={item.moderation}\n            parentAuthor={item.parentAuthor}\n            showReplyTo={row.showReplyTo}\n            isThreadParent={isThreadParentAt(slice.items, indexInSlice)}\n            isThreadChild={isThreadChildAt(slice.items, indexInSlice)}\n            isThreadLastChild={\n              isThreadChildAt(slice.items, indexInSlice) &&\n              slice.items.length === indexInSlice + 1\n            }\n            isParentBlocked={item.isParentBlocked}\n            isParentNotFound={item.isParentNotFound}\n            hideTopBorder={rowIndex === 0 && indexInSlice === 0}\n            rootPost={slice.items[0].post}\n            onShowLess={onPressShowLess}\n          />\n        )\n      } else if (row.type === 'sliceViewFullThread') {\n        return <ViewFullThread uri={row.uri} />\n      } else if (row.type === 'videoGridRowPlaceholder') {\n        return (\n          <View>\n            <PostFeedVideoGridRowPlaceholder />\n            <PostFeedVideoGridRowPlaceholder />\n            <PostFeedVideoGridRowPlaceholder />\n          </View>\n        )\n      } else if (row.type === 'videoGridRow') {\n        let sourceContext: VideoFeedSourceContext\n        if (feedType === 'author') {\n          sourceContext = {\n            type: 'author',\n            did: feedUriOrActorDid,\n            filter: feedTab as AuthorFilter,\n          }\n        } else {\n          sourceContext = {\n            type: 'feedgen',\n            uri: row.sourceFeedUri,\n            sourceInterstitial: feedCacheKey ?? 'none',\n          }\n        }\n\n        return (\n          <PostFeedVideoGridRow\n            items={row.items}\n            sourceContext={sourceContext}\n          />\n        )\n      } else if (row.type === 'showLessFollowup') {\n        return <ShowLessFollowup />\n      } else {\n        return null\n      }\n    },\n    [\n      renderEmptyState,\n      isPageFillLimited,\n      feed,\n      error,\n      onPressTryAgain,\n      savedFeedConfig,\n      l,\n      onPressRetryLoadMore,\n      feedType,\n      feedUriOrActorDid,\n      feedTab,\n      feedCacheKey,\n      onPressShowLess,\n      t,\n    ],\n  )\n\n  const shouldRenderPageFillLimit =\n    isPageFillLimited && !isEmpty && !isFetching && !isError\n  const shouldRenderEndOfFeed =\n    !hasNextPage &&\n    !isPageFillLimited &&\n    !isEmpty &&\n    !isFetching &&\n    !isError &&\n    !!renderEndOfFeed\n  const bottomBarOffset = useBottomBarOffset()\n  const FeedFooter = useCallback(() => {\n    /*\n     * A bit of padding at the bottom of the feed as you scroll and when you\n     * reach the end, so that content isn't cut off by the bottom of the\n     * screen. On mobile web, also clear the fixed bottom bar; on native the\n     * doubled headerOffset already covers the tab bar.\n     */\n    const offset =\n      Math.max(headerOffset, 32) * (IS_WEB ? 1 : 2) +\n      (IS_WEB ? bottomBarOffset : 0)\n\n    return isFetchingNextPage ? (\n      <View style={[styles.feedFooter]}>\n        <ActivityIndicator />\n        <View style={{height: offset}} />\n      </View>\n    ) : shouldRenderPageFillLimit ? (\n      <View style={{minHeight: offset}}>\n        <RepliesFeedLimited hasPosts />\n      </View>\n    ) : shouldRenderEndOfFeed ? (\n      <View style={{minHeight: offset}}>{renderEndOfFeed()}</View>\n    ) : (\n      <View style={{height: offset}} />\n    )\n  }, [\n    isFetchingNextPage,\n    shouldRenderPageFillLimit,\n    shouldRenderEndOfFeed,\n    renderEndOfFeed,\n    headerOffset,\n    bottomBarOffset,\n  ])\n\n  const liveNowConfig = useLiveNowConfig()\n\n  const seenActorWithStatusRef = useRef<Set<string>>(new Set())\n  const seenPostUrisRef = useRef<Set<string>>(new Set())\n  // Tracks every post we've seen so we can fire per-post events exactly once,\n  // regardless of the post's position within its slice.\n  const seenPerPostUrisRef = useRef<Set<string>>(new Set())\n\n  // Helper to calculate position in feed (count only root posts, not interstitials or thread replies)\n  const getPostPosition = useNonReactiveCallback(\n    (type: FeedRow['type'], key: string) => {\n      // Calculate position: find the row index in feedItems, then calculate position\n      const rowIndex = feedItems.findIndex(\n        row => row.type === 'sliceItem' && row.key === key,\n      )\n\n      if (rowIndex >= 0) {\n        let position = 0\n        for (let i = 0; i < rowIndex && i < feedItems.length; i++) {\n          const row = feedItems[i]\n          if (row.type === 'sliceItem') {\n            // Only count root posts (indexInSlice === 0), not thread replies\n            if (row.indexInSlice === 0) {\n              position++\n            }\n          } else if (row.type === 'videoGridRow') {\n            // Count each video in the grid row\n            position += row.items.length\n          }\n        }\n        return position\n      }\n    },\n  )\n\n  const onItemSeen = useCallback(\n    (item: FeedRow) => {\n      feedFeedback.onItemSeen(item)\n\n      // Events that should fire exactly once for every new post, regardless of\n      // its position within a slice or video grid row.\n      const onPostSeen = (post: app.bsky.feed.defs.PostView) => {\n        if (seenPerPostUrisRef.current.has(post.uri)) return\n        seenPerPostUrisRef.current.add(post.uri)\n\n        // Standard site embed view tracking\n        if (\n          bsky.isType(app.bsky.embed.external.view, post.embed) &&\n          isStandardSiteEmbed(post.embed.external)\n        ) {\n          ax.metric('embed:standardSite:view', {url: post.embed.external.uri})\n        }\n\n        // Photo embed impression tracking\n        if (\n          bsky.isType(app.bsky.embed.images.view, post.embed) ||\n          bsky.isType(app.bsky.embed.gallery.view, post.embed)\n        ) {\n          const totalImages = bsky.isType(\n            app.bsky.embed.gallery.view,\n            post.embed,\n          )\n            ? post.embed.items.filter(item =>\n                bsky.isType(app.bsky.embed.gallery.viewImage, item),\n              ).length\n            : post.embed.images.length\n          const useExpandedLayout = bsky.isType(\n            app.bsky.embed.gallery.view,\n            post.embed,\n          )\n            ? totalImages > 4\n            : ax.features.enabled(ax.features.PostGalleryEmbedEnable)\n          const layout =\n            totalImages === 1\n              ? 'single'\n              : useExpandedLayout\n                ? 'carousel'\n                : 'grid'\n\n          ax.metric('post:photoEmbed:impression', {\n            layout,\n            totalImages,\n            postUri: post.uri,\n            postAuthorDid: post.author.did,\n            feedDescriptor: feedFeedback.feedDescriptor || feed,\n          })\n        }\n      }\n\n      // Track post:view events\n      if (item.type === 'sliceItem') {\n        const slice = item.slice\n        const indexInSlice = item.indexInSlice\n        const postItem = slice.items[indexInSlice]\n        const post = postItem.post\n\n        onPostSeen(post)\n\n        // Track the post selected by the feed once it is actually visible.\n        if (\n          post.uri === slice.feedPostUri &&\n          !seenPostUrisRef.current.has(post.uri)\n        ) {\n          seenPostUrisRef.current.add(post.uri)\n\n          const position = getPostPosition(\n            'sliceItem',\n            slice.items[0]._reactKey,\n          )\n\n          ax.metric('post:view', {\n            uri: post.uri,\n            authorDid: post.author.did,\n            isReply: !!postItem.record.reply,\n            logContext: 'FeedItem',\n            feedDescriptor: feedFeedback.feedDescriptor || feed,\n            position,\n          })\n        }\n\n        // Live status tracking (existing code)\n        const actor = post.author\n        if (\n          actor.status &&\n          isStatusValidForViewers(actor.status, liveNowConfig) &&\n          isStatusStillActive(actor.status.expiresAt)\n        ) {\n          if (!seenActorWithStatusRef.current.has(actor.did)) {\n            seenActorWithStatusRef.current.add(actor.did)\n            ax.metric('live:view:post', {\n              subject: actor.did,\n              feed,\n            })\n          }\n        }\n      } else if (item.type === 'videoGridRow') {\n        // Track each video in the grid row\n        for (let i = 0; i < item.items.length; i++) {\n          const postItem = item.items[i]\n          const post = postItem.post\n\n          if (!seenPostUrisRef.current.has(post.uri)) {\n            seenPostUrisRef.current.add(post.uri)\n\n            const position = getPostPosition('videoGridRow', item.key)\n\n            ax.metric('post:view', {\n              uri: post.uri,\n              authorDid: post.author.did,\n              isReply: !!postItem.record.reply,\n              logContext: 'FeedItem',\n              feedDescriptor: feedFeedback.feedDescriptor || feed,\n              position,\n            })\n          }\n        }\n      }\n    },\n    [feedFeedback, feed, liveNowConfig, getPostPosition, ax],\n  )\n\n  return (\n    <View testID={testID} style={style}>\n      <List\n        testID={testID ? `${testID}-flatlist` : undefined}\n        ref={scrollElRef}\n        data={feedItems}\n        keyExtractor={(item: FeedRow) => item.key}\n        renderItem={renderItem}\n        ListFooterComponent={FeedFooter}\n        ListHeaderComponent={ListHeaderComponent}\n        refreshing={isPTRing}\n        onRefresh={() => void onRefresh()}\n        headerOffset={headerOffset}\n        progressViewOffset={progressViewOffset}\n        contentContainerStyle={{\n          minHeight: Dimensions.get('window').height * 1.5,\n        }}\n        onScrolledDownChange={handleScrolledDownChange}\n        onEndReached={() => void onEndReached()}\n        onEndReachedThreshold={2} // screen heights from the end, not posts\n        removeClippedSubviews={true}\n        extraData={extraData}\n        desktopFixedHeight={\n          desktopFixedHeightOffset ? desktopFixedHeightOffset : true\n        }\n        initialNumToRender={initialNumToRenderOverride ?? initialNumToRender}\n        windowSize={9}\n        maxToRenderPerBatch={IS_IOS ? 5 : 1}\n        updateCellsBatchingPeriod={40}\n        onItemSeen={onItemSeen}\n      />\n    </View>\n  )\n}","file":"src/view/com/posts/PostFeed.tsx","kind":"component","line":206,"members":{"FeedFooter":[964,996],"ListHeaderComponent":[206,255],"ageAssuranceBannerState":[412,412],"ax":[256,256],"blockedOrMutedAuthors":[421,424],"bottomBarOffset":[963,963],"checkForNew":[323,346],"description":[206,255],"desktopFixedHeightOffset":[206,255],"disablePoll":[206,255],"enabled":[206,255],"extraData":[206,255],"feed":[206,255],"feedFeedback":[262,262],"feedItems":[426,742],"feedParams":[206,255],"feedType":[266,266],"followAndLikeProgressGuide":[405,405],"followProgressGuide":[404,404],"getPostPosition":[1007,1031],"handleScrolledDownChange":[349,352],"hasPressedShowLessUris":[280,282],"headerOffset":[206,255],"ignoreFilterFor":[206,255],"initialNumToRender":[261,261],"initialNumToRenderOverride":[206,255],"isCurrentFeedAtStartupSelected":[419,419],"isEmpty":[312,315],"isPTRing":[263,263],"isScrolledDownRef":[348,348],"isVideoFeed":[206,255],"lastFetchRef":[265,265],"liveNowConfig":[998,998],"onEndReached":[776,798],"onHasNew":[206,255],"onItemSeen":[1033,1157],"onPostCreated":[355,367],"onPressRetryLoadMore":[805,807],"onPressShowLess":[283,292],"onPressTryAgain":[800,803],"onRefresh":[766,770],"onScrolledDownChange":[206,255],"opts":[295,298],"pollInterval":[206,255],"progressViewOffset":[206,255],"queryClient":[259,259],"ref":[206,255],"refreshFeed":[748,764],"renderEmptyState":[206,255],"renderEndOfFeed":[206,255],"renderItem":[812,952],"savedFeedConfig":[206,255],"scrollElRef":[206,255],"seenActorWithStatusRef":[1000,1000],"seenPerPostUrisRef":[1004,1004],"seenPostUrisRef":[1001,1001],"selectedFeed":[413,413],"style":[206,255],"t":[257,257],"testID":[206,255],"videoGridColumns":[267,267]},"supers":[]},"PostFeedErrorMessage":{"appearsIn":[["home","h-widgets","Screen \u00b7 component composition"]],"code":"export function PostFeedErrorMessage({\n  feedDesc,\n  error,\n  onPressTryAgain,\n  savedFeedConfig,\n}: {\n  feedDesc: FeedDescriptor\n  error?: Error\n  onPressTryAgain: () => void\n  savedFeedConfig?: app.bsky.actor.defs.SavedFeed\n}) {\n  const {_: _l} = useLingui()\n  const knownError = useMemo(\n    () => detectKnownError(feedDesc, error),\n    [feedDesc, error],\n  )\n\n  if (\n    typeof knownError !== 'undefined' &&\n    knownError !== KnownError.Unknown &&\n    feedDesc.startsWith('feedgen')\n  ) {\n    return (\n      <FeedgenErrorMessage\n        feedDesc={feedDesc}\n        knownError={knownError}\n        rawError={error}\n        savedFeedConfig={savedFeedConfig}\n      />\n    )\n  }\n\n  if (knownError === KnownError.Block) {\n    return (\n      <EmptyState\n        icon={WarningIcon}\n        iconSize=\"2xl\"\n        message={_l(msgLingui`Posts hidden`)}\n        style={{paddingVertical: 40}}\n      />\n    )\n  }\n\n  return (\n    <ErrorMessage\n      message={cleanError(error)}\n      onPressTryAgain={onPressTryAgain}\n    />\n  )\n}","file":"src/view/com/posts/PostFeedErrorMessage.tsx","kind":"component","line":37,"members":{"error":[37,47],"feedDesc":[37,47],"knownError":[49,52],"onPressTryAgain":[37,47],"savedFeedConfig":[37,47]},"supers":[]},"PostFeedItem":{"appearsIn":[["home","h-widgets","Screen \u00b7 component composition"]],"code":"export function PostFeedItem({\n  post,\n  record,\n  postNumbering,\n  reason,\n  feedContext,\n  reqId,\n  moderation,\n  parentAuthor,\n  showReplyTo,\n  isThreadChild,\n  isThreadLastChild,\n  isThreadParent,\n  hideTopBorder,\n  isParentBlocked,\n  isParentNotFound,\n  rootPost,\n  onShowLess,\n}: FeedItemProps & {\n  post: app.bsky.feed.defs.PostView\n  rootPost: app.bsky.feed.defs.PostView\n  onShowLess?: (interaction: app.bsky.feed.defs.Interaction) => void\n}): React.ReactNode {\n  const postShadowed = usePostShadow(post)\n  const richText = useMemo(\n    () =>\n      new RichTextAPI({\n        text: record.text,\n        facets: record.facets,\n      }),\n    [record],\n  )\n  if (postShadowed === POST_TOMBSTONE) {\n    return null\n  }\n  if (richText && moderation) {\n    const feedItem: FeedItem = {\n      uri: postShadowed.uri,\n      authorDid: postShadowed.author.did,\n      feedContext,\n      reqId,\n      via: repostVia(reason),\n    }\n    return (\n      <ReportDialogMetadataContext.Provider key={postShadowed.uri}>\n        <FeedItemProvider value={feedItem}>\n          <FeedItemInner\n            post={postShadowed}\n            record={record}\n            postNumbering={postNumbering}\n            reason={reason}\n            feedContext={feedContext}\n            reqId={reqId}\n            richText={richText}\n            parentAuthor={parentAuthor}\n            showReplyTo={showReplyTo}\n            moderation={moderation}\n            isThreadChild={isThreadChild}\n            isThreadLastChild={isThreadLastChild}\n            isThreadParent={isThreadParent}\n            hideTopBorder={hideTopBorder}\n            isParentBlocked={isParentBlocked}\n            isParentNotFound={isParentNotFound}\n            rootPost={rootPost}\n            onShowLess={onShowLess}\n          />\n        </FeedItemProvider>\n      </ReportDialogMetadataContext.Provider>\n    )\n  }\n  return null\n}","file":"src/view/com/posts/PostFeedItem.tsx","kind":"component","line":85,"members":{"feedContext":[85,107],"hideTopBorder":[85,107],"isParentBlocked":[85,107],"isParentNotFound":[85,107],"isThreadChild":[85,107],"isThreadLastChild":[85,107],"isThreadParent":[85,107],"moderation":[85,107],"onShowLess":[85,107],"parentAuthor":[85,107],"post":[85,107],"postNumbering":[85,107],"postShadowed":[108,108],"reason":[85,107],"record":[85,107],"reqId":[85,107],"richText":[109,116],"rootPost":[85,107],"showReplyTo":[85,107]},"supers":[]},"SuggestedFollows":{"appearsIn":[["home","h-widgets","Screen \u00b7 component composition"]],"code":"export function SuggestedFollows({feed}: {feed: FeedDescriptor}) {\n  const {currentAccount} = useSession()\n  const [feedType, feedUriOrDid] = feed.split('|')\n  if (feedType === 'author') {\n    if (currentAccount?.did === feedUriOrDid) {\n      return null\n    } else {\n      return <SuggestedFollowsProfile did={feedUriOrDid} />\n    }\n  } else {\n    return <SuggestedFollowsHome />\n  }\n}","file":"src/components/FeedInterstitials.tsx","kind":"component","line":112,"members":{"feed":[112,112],"feedType":[114,114]},"supers":[]},"usePostFeedQuery":{"alsoIn":["src/features/followingV2/home/queries/postFeed.ts"],"appearsIn":[["home","h-classes","Logic \u00b7 class diagram"],["home","h-sequence","Scroll the Following feed \u00b7 sequence"],["profile","h-classes","Logic \u00b7 class diagram"]],"code":"export function usePostFeedQuery(\n  feedDesc: FeedDescriptor,\n  params?: FeedParams,\n  opts?: {enabled?: boolean; ignoreFilterFor?: string},\n) {\n  const feedTuners = useFeedTuners(feedDesc)\n  const moderationOpts = useModerationOpts()\n  const {data: preferences} = usePreferencesQuery()\n  /**\n   * Load bearing: we need to await AA state or risk FOUC. This marginally\n   * delays feeds, but AA state is fetched immediately on load and is then\n   * available for the remainder of the session, so this delay only affects cold\n   * loads. -esb\n   */\n  const enabled =\n    opts?.enabled !== false && Boolean(moderationOpts) && Boolean(preferences)\n  const userInterests = aggregateUserInterests(preferences)\n  const followingPinnedIndex =\n    preferences?.savedFeeds?.findIndex(\n      f => f.pinned && f.value === 'following',\n    ) ?? -1\n  const enableFollowingToDiscoverFallback = followingPinnedIndex === 0\n  const {hasSession} = useSession()\n  const client = useAppviewClient()\n  const lastRun = useRef<{\n    data: InfiniteData<FeedPageUnselected>\n    args: typeof selectArgs\n    result: InfiniteData<FeedPage>\n  } | null>(null)\n  const isDiscover = feedDesc.includes(DISCOVER_FEED_URI)\n\n  /**\n   * The number of posts to fetch in a single request. Because we filter\n   * unwanted content, we may over-fetch here to try and fill pages by\n   * `MIN_POSTS`. But if you're doing this, ask @why if it's ok first.\n   */\n  const fetchLimit = MIN_POSTS\n\n  // Make sure this doesn't invalidate unless really needed.\n  const selectArgs = useMemo(\n    () => ({\n      feedTuners,\n      moderationOpts,\n      ignoreFilterFor: opts?.ignoreFilterFor,\n      isDiscover,\n    }),\n    [feedTuners, moderationOpts, opts?.ignoreFilterFor, isDiscover],\n  )\n\n  const query = useInfiniteQuery<\n    FeedPageUnselected,\n    Error,\n    InfiniteData<FeedPage>,\n    QueryKey,\n    RQPageParam\n  >({\n    enabled,\n    staleTime: STALE.INFINITY,\n    queryKey: RQKEY(feedDesc, params),\n    async queryFn({pageParam}: {pageParam: RQPageParam}) {\n      logger.debug('usePostFeedQuery', {feedDesc, cursor: pageParam?.cursor})\n      const {api, cursor} = pageParam\n        ? pageParam\n        : {\n            api: createApi({\n              feedDesc,\n              feedParams: params || {},\n              feedTuners,\n              client,\n              // Not in the query key because they don't change:\n              userInterests,\n              // Not in the query key. Reacting to it switching isn't important:\n              enableFollowingToDiscoverFallback,\n            }),\n            cursor: undefined,\n          }\n\n      const res = await api.fetch({cursor, limit: fetchLimit})\n\n      /*\n       * If this is a public view, we need to check if posts fail moderation.\n       * If all fail, we throw an error. If only some fail, we continue and let\n       * moderations happen later, which results in some posts being shown and\n       * some not.\n       */\n      if (!hasSession) {\n        assertSomePostsPassModeration(\n          res.feed,\n          preferences?.moderationPrefs ||\n            DEFAULT_LOGGED_OUT_PREFERENCES.moderationPrefs,\n        )\n      }\n\n      return {\n        api,\n        cursor: res.cursor,\n        feed: res.feed,\n        fetchedAt: Date.now(),\n      }\n    },\n    initialPageParam: undefined,\n    getNextPageParam: lastPage =>\n      lastPage.cursor\n        ? {\n            api: lastPage.api,\n            cursor: lastPage.cursor,\n          }\n        : undefined,\n    select: useCallback(\n      (data: InfiniteData<FeedPageUnselected, RQPageParam>) => {\n        // If the selection depends on some data, that data should\n        // be included in the selectArgs object and read here.\n        const {feedTuners, moderationOpts, ignoreFilterFor, isDiscover} =\n          selectArgs\n\n        const tuner = new FeedTuner(feedTuners)\n\n        // Keep track of the last run and whether we can reuse\n        // some already selected pages from there.\n        let reusedPages = []\n        if (lastRun.current) {\n          const {\n            data: lastData,\n            args: lastArgs,\n            result: lastResult,\n          } = lastRun.current\n          let canReuse = true\n          for (let key in selectArgs) {\n            if (selectArgs.hasOwnProperty(key)) {\n              if ((selectArgs as any)[key] !== (lastArgs as any)[key]) {\n                // Can't do reuse anything if any input has changed.\n                canReuse = false\n                break\n              }\n            }\n          }\n          if (canReuse) {\n            for (let i = 0; i < data.pages.length; i++) {\n              if (data.pages[i] && lastData.pages[i] === data.pages[i]) {\n                reusedPages.push(lastResult.pages[i])\n                // Keep the tuner in sync so that the end result is deterministic.\n                tuner.tune(lastData.pages[i].feed)\n                continue\n              }\n              // Stop as soon as pages stop matching up.\n              break\n            }\n          }\n        }\n\n        const result = {\n          pageParams: data.pageParams,\n          pages: [\n            ...reusedPages,\n            ...data.pages.slice(reusedPages.length).map(page => ({\n              api: page.api,\n              tuner,\n              cursor: page.cursor,\n              fetchedAt: page.fetchedAt,\n              slices: tuner\n                .tune(page.feed)\n                .map(slice => {\n                  const moderations = slice.items.map(item =>\n                    moderatePost(item.post, moderationOpts!),\n                  )\n\n                  // apply moderation filter\n                  for (let i = 0; i < slice.items.length; i++) {\n                    const ignoreFilter =\n                      slice.items[i].post.author.did === ignoreFilterFor\n                    if (ignoreFilter) {\n                      // remove mutes to avoid confused UIs\n                      moderations[i].causes = moderations[i].causes.filter(\n                        cause => cause.type !== 'muted',\n                      )\n                    }\n                    if (\n                      !ignoreFilter &&\n                      moderations[i]?.ui('contentList').filter\n                    ) {\n                      return undefined\n                    }\n                  }\n\n                  if (isDiscover) {\n                    userActionHistory.seen(\n                      slice.items.map(item => ({\n                        feedContext: slice.feedContext,\n                        reqId: slice.reqId,\n                        likeCount: item.post.likeCount ?? 0,\n                        repostCount: item.post.repostCount ?? 0,\n                        replyCount: item.post.replyCount ?? 0,\n                        isFollowedBy: Boolean(\n                          item.post.author.viewer?.followedBy,\n                        ),\n                        uri: item.post.uri,\n                      })),\n                    )\n                  }\n\n                  const feedPostSlice: FeedPostSlice = {\n                    _reactKey: slice._reactKey,\n                    _isFeedPostSlice: true,\n                    isIncompleteThread: slice.isIncompleteThread,\n                    isFallbackMarker: slice.isFallbackMarker,\n                    feedContext: slice.feedContext,\n                    reqId: slice.reqId,\n                    reason: slice.reason,\n                    feedPostUri: slice.feedPostUri,\n                    items: slice.items.map((item, i) => {\n                      const feedPostSliceItem: FeedPostSliceItem = {\n                        _reactKey: `${slice._reactKey}-${i}-${item.post.uri}`,\n                        uri: item.post.uri,\n                        post: item.post,\n                        record: item.record,\n                        postNumbering: item.postNumbering,\n                        moderation: moderations[i],\n                        parentAuthor: item.parentAuthor,\n                        isParentBlocked: item.isParentBlocked,\n                        isParentNotFound: item.isParentNotFound,\n                      }\n                      return feedPostSliceItem\n                    }),\n                  }\n                  return feedPostSlice\n                })\n                .filter(n => !!n),\n            })),\n          ],\n        }\n        // Save for memoization.\n        lastRun.current = {data, result, args: selectArgs}\n        return result\n      },\n      [selectArgs /* Don't change. Everything needs to go into selectArgs. */],\n    ),\n  })\n\n  let itemCount = 0\n  for (const page of query.data?.pages || []) {\n    for (const slice of page.slices) {\n      itemCount += slice.items.length\n    }\n  }\n  /**\n   * Repost-heavy profiles can leave Replies sparse even with server filtering.\n   * Keep this five-request hard stop Replies-only; other feeds can be sparse\n   * due to moderation but retain their existing pagination behavior.\n   */\n  const isPageFillLimited =\n    feedDesc.startsWith('author|') &&\n    feedDesc.endsWith('|posts_and_replies_only') &&\n    hasReachedPageFillLimit(query.data?.pages, MIN_POSTS)\n  const paginatedQuery = {\n    ...query,\n    isPageFillLimited,\n    hasNextPage: query.hasNextPage && !isPageFillLimited,\n    fetchNextPage: (...args: Parameters<typeof query.fetchNextPage>) =>\n      isPageFillLimited ? Promise.resolve(query) : query.fetchNextPage(...args),\n  }\n  useAutoPagination(paginatedQuery, itemCount, MIN_POSTS)\n\n  return paginatedQuery\n}","file":"src/state/queries/post-feed.ts","kind":"hook","line":138,"members":{"client":[161,161],"feedTuners":[143,143],"lastRun":[162,166],"moderationOpts":[144,144],"query":[187,374],"selectArgs":[177,185]},"supers":[]}},"sourceUrl":"https://github.com/bluesky-social/social-app/blob/f7399a645c08dcf5d15f8cac64417ac73fe6ddf9/"};
